  confidence: "limited",
  metrics: {
    activeListings: {
      value: 12
    },
    medianPrice: {
      value: "₹48L"
    },
    mostSearchedBudget: {
      value: null
    },
    // not enough searches yet
    avgListingQuality: {
      value: null
    },
    // suppressed by k-anon
    freshListings: {
      value: 4
    }
  },
  good: ["A handful of plots are live near the coast right now.", "The current median price suggests this is a mid-budget area."],
  check: ["We don't yet have a reliable read on what most buyers here search for.", "Confirm location and key details directly with the lister before visiting.", "You can still view all live homes in this area below."]
