    let list;
    if (sc.kind === "AREA_SET" || sc.kind === "HIERARCHY") list = EX.inAreas(sc.areaKeys, st.filters);else if (sc.kind === "CITY") list = EX.listings.filter(l => EX.passes(l, st.filters));else if (sc.kind === "POLYGON") list = EX.inPoly(sc.poly, st.filters);else if (sc.kind === "VIEWPORT") list = EX.inBounds(sc.bounds, st.filters);else return [];
