// ---- formatters + geo helpers ----
window.BLR_DIST = function (a, b) {
  if (!a || !b || a.lat == null || a.lon == null || b.lat == null || b.lon == null) return null;
  const R = 6371,
    toRad = d => d * Math.PI / 180;
  const dLat = toRad(b.lat - a.lat),
    dLon = toRad(b.lon - a.lon);
  const s = Math.sin(dLat / 2) ** 2 + Math.cos(toRad(a.lat)) * Math.cos(toRad(b.lat)) * Math.sin(dLon / 2) ** 2;
  return R * 2 * Math.atan2(Math.sqrt(s), Math.sqrt(1 - s));
};
window.BLR_NOUN = function (mode, n) {
  if (mode === "Rent") return n === 1 ? "rental" : "rentals";
  return n === 1 ? "home for sale" : "homes for sale";
};
window.BLR_TITLE = function (mode) {
  return mode === "Rent" ? "Rentals" : "Homes for sale";
};
// Coarse compass direction (N/E/S/W) of `to` seen from `from` — powers agri origin reframing.
window.BLR_BEARING_DIR = function (from, to) {
  const dy = to.lat - from.lat;
  const dx = (to.lon - from.lon) * Math.cos(from.lat * Math.PI / 180);
  const ang = Math.atan2(dx, dy) * 180 / Math.PI; // 0=N, 90=E, ±180=S, -90=W
  if (ang >= -45 && ang < 45) return "N";
  if (ang >= 45 && ang < 135) return "E";
  if (ang <= -45 && ang > -135) return "W";
  return "S";
};
window.BLR_INR = function (p) {
  const cr = p / 10000000;
  if (cr >= 1) return `₹${cr.toFixed(2)} Cr`;
  return `₹${(p / 100000).toFixed(0)} L`;
};
window.BLR_INR_SHORT = function (p) {
  return p >= 10000000 ? `₹${(p / 10000000).toFixed(2)} Cr` : `₹${(p / 100000).toFixed(0)} L`;
};
