    "kaval-bairasandra": 2,
    ganganagar: 1,
    "amani-byrathikhane": 1,
    "vignana-kendra": 1,
    chelekere: 1,
    geddalahalli: 1,
    "k-narayanapura": 1,
    kyalasanahalli: 1,
    sampigehalli: 1,
